def segments(frontiers, n):
    """Maximal runs of indices between frontier lines, as (start, end) pairs."""
    s = []; prev = -1
    for x in list(frontiers) + [n]:
        if x - prev > 1: s.append((prev + 1, x))
        prev = x
    return s

def mirror_complete(grid):
    """Complete partial figures: a block's shape group is mirrored across a frontier
    column it touches, filling missing mirror cells — unless the group is already
    mirror-complete across the block's other frontier (it is the finished half)."""
    H, W = len(grid), len(grid[0])
    _, fc, frows, fcols = background_and_frontier(grid)
    rs = segments(frows, H); cs = segments(fcols, W)
    out = [row[:] for row in grid]
    def shape(v): return v not in (0, fc)
    def present(y, x):
        return 0 <= y < H and 0 <= x < W and shape(out[y][x])
    changed = True
    while changed:
        changed = False
        for r0, r1 in rs:
            for c0, c1 in cs:
                grp = [(y, x) for y in range(r0, r1) for x in range(c0, c1) if shape(out[y][x])]
                if not grp: continue
                fL = c0 - 1 if c0 - 1 in fcols else None
                fR = c1 if c1 in fcols else None
                for f in (fR, fL):
                    if f is None: continue
                    other = fL if f == fR else fR
                    if other is not None and all(present(y, 2 * other - x) for y, x in grp):
                        continue
                    if (c1 == f and any(x == f - 1 for y, x in grp)) or (c0 == f + 1 and any(x == f + 1 for y, x in grp)):
                        for y, x in grp:
                            nx = 2 * f - x
                            if 0 <= nx < W and out[y][nx] == 0:
                                out[y][nx] = out[y][x]; changed = True
    return out

